<?php
require_once __DIR__.'/../includes/functions.php';require_role(['super_admin','admin']);verify_csrf();$db=db();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=post_string('status',20);if($id&&in_array($status,['new','in_progress','resolved'],true)){$s=$db->prepare('UPDATE inquiries SET status=? WHERE id=?');$s->execute([$status,$id]);audit(current_user()['id'],'INQUIRY_STATUS_CHANGED','inquiries',(string)$id,'Status: '.$status);flash('success','Inquiry status updated.');redirect('reports/inquiries.php');}}$rows=$db->query('SELECT * FROM inquiries ORDER BY created_at DESC LIMIT 300')->fetchAll();$pageTitle='Contact inquiries';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Front desk','Contact inquiries','Review public messages and appointment inquiries.');?>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Received</th><th>Contact</th><th>Type</th><th>Message</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td data-no-i18n><?=e($r['created_at'])?></td><td><strong data-no-i18n><?=e($r['name'])?></strong><div class="small-muted" data-no-i18n><?=e($r['email'])?><br><?=e($r['phone'])?></div></td><td><?=e(ucwords($r['inquiry_type']))?></td><td data-no-i18n style="min-width:220px;white-space:normal"><?=nl2br(e($r['message']))?></td><td><?=status_badge($r['status'])?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach(['new','in_progress','resolved'] as $st):?><option value="<?=$st?>" <?=$r['status']===$st?'selected':''?>><?=e(ucwords(str_replace('_',' ',$st)))?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-primary">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows)echo empty_row(6,'No inquiries received.');?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>